@font-face{font-family:'Playfair Display';font-style:normal;font-weight:400;font-display:swap;src:url('/wp-content/uploads/nortear/fonts/playfair-400.woff2') format('woff2');}
@font-face{font-family:'Playfair Display';font-style:italic;font-weight:400;font-display:swap;src:url('/wp-content/uploads/nortear/fonts/playfair-400i.woff2') format('woff2');}
@font-face{font-family:'Playfair Display';font-style:normal;font-weight:700;font-display:swap;src:url('/wp-content/uploads/nortear/fonts/playfair-700.woff2') format('woff2');}
@font-face{font-family:'Playfair Display';font-style:normal;font-weight:900;font-display:swap;src:url('/wp-content/uploads/nortear/fonts/playfair-900.woff2') format('woff2');}
@font-face{font-family:'DM Sans';font-style:normal;font-weight:400;font-display:swap;src:url('/wp-content/uploads/nortear/fonts/dmsans-400.woff2') format('woff2');}
@font-face{font-family:'DM Sans';font-style:normal;font-weight:500;font-display:swap;src:url('/wp-content/uploads/nortear/fonts/dmsans-500.woff2') format('woff2');}
@font-face{font-family:'DM Sans';font-style:normal;font-weight:600;font-display:swap;src:url('/wp-content/uploads/nortear/fonts/dmsans-600.woff2') format('woff2');}
@font-face{font-family:'DM Sans';font-style:normal;font-weight:700;font-display:swap;src:url('/wp-content/uploads/nortear/fonts/dmsans-700.woff2') format('woff2');}
@font-face{font-family:'DM Mono';font-style:normal;font-weight:400;font-display:swap;src:url('/wp-content/uploads/nortear/fonts/dmmono-400.woff2') format('woff2');}
@font-face{font-family:'DM Mono';font-style:normal;font-weight:500;font-display:swap;src:url('/wp-content/uploads/nortear/fonts/dmmono-500.woff2') format('woff2');}
.nm-accent{color:#F47C20;font-style:italic;font-weight:400;}
.nm-i, .nm-i p{font-style:italic;}
.nm-herosub{border-left:3px solid #F47C20;padding-left:20px;max-width:560px;}
.nm-stepnum{opacity:.35;}
.nm-badge{display:inline-block;text-transform:uppercase;position:absolute;top:16px;left:16px;z-index:2;}
.nm-card{position:relative;overflow:hidden;}
.nm-card .elementor-widget-image img{height:240px;object-fit:cover;width:100%;display:block;}
.nm-card .elementor-widget{padding-left:24px;padding-right:24px;}
.nm-card .elementor-widget-image{padding-left:0;padding-right:0;}
@media(max-width:767px){
  .nm-herosub{border-left:none;border-top:3px solid #F47C20;padding-left:0;padding-top:16px;text-align:center;max-width:none;}
  .nm-herofoot{justify-content:center;}
}
